"""Thin wrapper around a fastText engine, plus provenance reporting.

Engine preference order:
  1. an already importable `fasttext` extension module (the authors' C++ code, requirements R2-R5,
     R12 - hierarchical softmax + asynchronous SGD are the compiled defaults);
  2. `pip install fasttext-wheel` (same upstream C++ source, prebuilt, no POSIX toolchain needed);
  3. a native build of the cloned repo (repo/Makefile or `pip install .`) if a toolchain exists;
  4. pure-numpy re-implementation (words + hashed bigrams, averaged embeddings, softmax, SGD with
     linearly decaying lr).  This is a re-implementation of the paper's description, so a run that
     uses it is flagged as such in metrics.json.

Arguments are always forwarded verbatim (dim / wordNgrams / epoch / lr / thread / bucket / minCount /
minn / maxn / loss) so nothing of the authors' configuration is rewritten.
"""

import importlib
import json
import os
import shutil
import subprocess
import sys
import time

REPO_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "repo")


def _log(msg):
    print(msg, flush=True)


class Engine:
    def __init__(self, name, impl, version=None, git_hash=None):
        self.name = name            # 'fasttext-wheel' | 'fasttext (preinstalled)' | 'native build' | 'numpy re-implementation'
        self.impl = impl
        self.version = version
        self.git_hash = git_hash
        self.is_reimplementation = name == "numpy re-implementation"

    def train(self, input_path, output_path, **kwargs):
        if self.name == "numpy re-implementation":
            model = self.impl.NumpyFastText(**kwargs)
            model.fit(input_path, verbose=kwargs.pop("verbose", 2) if False else 0)
            return model
        return self.impl.train_supervised(input=input_path, output=output_path, **kwargs)

    def test(self, model, path):
        if self.name == "numpy re-implementation":
            return model.test(path)
        return model.test(path)

    def save(self, model, path):
        if self.name == "numpy re-implementation":
            return model.save(path)
        model.save_model(path)
        return path


def repo_git_hash():
    try:
        out = subprocess.run(["git", "-C", REPO_DIR, "rev-parse", "HEAD"],
                             capture_output=True, text=True, timeout=30)
        if out.returncode == 0:
            return out.stdout.strip()
    except Exception:  # noqa: BLE001
        pass
    return None


def get_engine(allowed_pip=True, verbose=True):
    """Return the best available Engine."""
    try:
        ft = importlib.import_module("fasttext")
        if verbose:
            _log("engine: using preinstalled fasttext module %s" % getattr(ft, "__file__", "?"))
        return Engine("fasttext (preinstalled)", ft, getattr(ft, "__version__", None),
                      repo_git_hash())
    except ImportError:
        pass

    if allowed_pip:
        try:
            if verbose:
                _log("engine: fasttext not importable, trying pip install fasttext-wheel ...")
            subprocess.run([sys.executable, "-m", "pip", "install", "fasttext-wheel"],
                           check=True, capture_output=True, text=True, timeout=600)
            ft = importlib.import_module("fasttext")
            if verbose:
                _log("engine: fasttext-wheel installed (%s)" % getattr(ft, "__file__", "?"))
            return Engine("fasttext-wheel", ft, getattr(ft, "__version__", None), repo_git_hash())
        except Exception as e:  # noqa: BLE001
            _log("engine: pip install fasttext-wheel failed (%s: %s)" % (type(e).__name__, e))

    # native build of the authors' repo
    make = shutil.which("make")
    if make and os.path.exists(os.path.join(REPO_DIR, "Makefile")):
        try:
            _log("engine: trying `make` in repo/ ...")
            subprocess.run([make], cwd=REPO_DIR, check=True, capture_output=True, text=True,
                           timeout=900)
            if os.path.exists(os.path.join(REPO_DIR, "fasttext")):
                return NativeEngine("native build")
        except Exception as e:  # noqa: BLE001
            _log("engine: native make failed (%s: %s)" % (type(e).__name__, e))

    _log("engine: falling back to the pure-numpy re-implementation (results flagged as such)")
    return Engine("numpy re-implementation", sys.modules[__name__], git_hash=repo_git_hash())


class NativeEngine(Engine):
    """Wraps the compiled ./fasttext binary through subprocess (same code path as the paper)."""

    def __init__(self, name):
        super().__init__(name, None, version="native-build", git_hash=repo_git_hash())
        self.bin = os.path.join(REPO_DIR, "fasttext")

    def train(self, input_path, output_path, **kwargs):
        cmd = [self.bin, "supervised", "-input", input_path, "-output", output_path]
        for k, v in kwargs.items():
            if k == "verbose":
                continue
            cmd += ["-%s" % k, str(v)]
        subprocess.run(cmd, check=True)
        return output_path + ".bin"

    def test(self, model, path):
        out = subprocess.run([self.bin, "test", model, path], check=True, capture_output=True,
                             text=True).stdout
        # fastText prints e.g. "N  0.925  0.925"
        fields = out.split()
        n, p1, r1 = int(fields[-3]), float(fields[-2]), float(fields[-1])
        return n, p1, r1

    def save(self, model, path):
        return model


